{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Urapidil absolute oral bioavailability was 78% (72-84%) in healthy male volunteers after a 30 mg oral solution versus IV bolus, well above the 20% threshold."
    },
    {
      "card_ids": ["C53"],
      "claim": "Ondansetron mean absolute bioavailability was 66% in healthy control subjects with normal liver function after a single 8 mg oral dose, supporting high bioavailability."
    },
    {
      "card_ids": ["C23"],
      "claim": "Acamprosate average oral bioavailability was about 11% under fasting conditions, the only sub-threshold result among the evidence molecules."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C23"],
  "decision_summary": "Nine evidence molecules report oral bioavailability values above 20%, many as direct absolute measurements in healthy subjects, while one molecule reports about 11% under fasting conditions with unspecified bioavailability type; the positive evidence outweighs the single less-direct negative record.",
  "evidence_gaps": [
    "Molecule 7 record group contains alfentanil values (C15, C08) under the alprazolam label; these inconsistent cards were discounted.",
    "Some positive evidence is qualitative or class-level (e.g., pirfenidone 'high', DPP-4 inhibitor class range) rather than numeric absolute measurements.",
    "The only sub-threshold record (C23) was measured under fasting conditions with unspecified bioavailability type, limiting directness."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C05", "C53"],
  "revision_action": "initial",
  "supportive_card_ids": ["C05", "C53"]
}

